"use client";
import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
} from "react";
import { cn } from "./lib/cn";
import { cssMs } from "./lib/motion-tokens";
import "./animated-counter.css";
function CounterDigit({
  digit,
  direction,
  reveal,
}: {
  digit: number;
  direction: "up" | "down" | "none";
  reveal: boolean;
}) {
  const column = useRef<HTMLSpanElement>(null),
    first = useRef(true);
  useLayoutEffect(() => {
    const element = column.current;
    if (!element) return;
    const animate = (initial = false) => {
      const tokens = getComputedStyle(element),
        height = element.parentElement!.getBoundingClientRect().height;
      const transform = tokens.transform;
      const offset =
        transform === "none"
          ? 20 + digit
          : -new DOMMatrixReadOnly(transform).m42 / height;
      const start = initial ? 20 : 20 + (((offset % 10) + 10) % 10);
      let end = 20 + digit;
      if (direction === "up" && end < start) end += 10;
      if (direction === "down" && end > start) end -= 10;
      element.getAnimations().forEach((animation) => animation.cancel());
      element.style.transform = `translateY(-${(20 + digit) * 1.2}em)`;
      if (
        !matchMedia("(prefers-reduced-motion: reduce)").matches &&
        (initial || direction !== "none")
      )
        element.animate(
          [
            { transform: `translateY(-${start * 1.2}em)` },
            { transform: `translateY(-${end * 1.2}em)` },
          ],
          {
            duration: cssMs(tokens.getPropertyValue("--duration-deliberate")),
            easing: tokens.getPropertyValue("--ease-out").trim(),
          },
        );
    };
    if (first.current) {
      first.current = false;
      element.style.transform = `translateY(-${(20 + digit) * 1.2}em)`;
      if (reveal) {
        const observer = new IntersectionObserver(
          (entries) => {
            if (entries[0].isIntersecting) {
              animate(true);
              observer.disconnect();
            }
          },
          { threshold: 0.6 },
        );
        observer.observe(element.parentElement!);
        return () => observer.disconnect();
      }
    } else animate();
  }, [digit, direction, reveal]);
  useEffect(() => {
    const preference = matchMedia("(prefers-reduced-motion: reduce)");
    const cancel = () => {
      if (preference.matches)
        column.current
          ?.getAnimations()
          .forEach((animation) => animation.cancel());
    };
    preference.addEventListener("change", cancel);
    return () => preference.removeEventListener("change", cancel);
  }, []);
  return (
    <span
      data-slot="counter-digit"
      className="inline-block h-[1.2em] w-[1ch] overflow-hidden"
    >
      <span
        ref={column}
        className="block"
        style={
          {
            transform: "translateY(calc(-1.2em * var(--counter-target)))",
            "--counter-target": 20 + digit,
          } as CSSProperties
        }
      >
        {Array.from({ length: 50 }, (_, i) => (
          <span key={i} className="block h-[1.2em] leading-[1.2]">
            {i % 10}
          </span>
        ))}
      </span>
    </span>
  );
}
export function AnimatedCounter({
  value,
  label,
  prefix = "",
  suffix = "",
  decimals = 0,
  locale = "en-US",
  animateOnView = false,
  className,
}: {
  value: number;
  label?: string;
  prefix?: string;
  suffix?: string;
  decimals?: number;
  locale?: string;
  animateOnView?: boolean;
  className?: string;
}) {
  const shell = useRef<HTMLSpanElement>(null),
    content = useRef<HTMLSpanElement>(null);
  useLayoutEffect(() => {
    const measure = () => {
      if (shell.current && content.current)
        shell.current.style.width = `${content.current.offsetWidth}px`;
    };
    measure();
    const observer = new ResizeObserver(measure);
    if (content.current) observer.observe(content.current);
    return () => observer.disconnect();
  }, []);
  const [frame, setFrame] = useState({ value, prior: value });
  if (!Object.is(frame.value, value)) setFrame({ value, prior: frame.value });
  const direction =
    value > frame.prior ? "up" : value < frame.prior ? "down" : "none";
  const text = Number.isFinite(value)
    ? new Intl.NumberFormat(locale, {
        minimumFractionDigits: Math.max(0, Math.min(20, decimals)),
        maximumFractionDigits: Math.max(0, Math.min(20, decimals)),
      }).format(value)
    : "—";
  return (
    <span
      data-slot="animated-counter"
      className={cn("inline-flex flex-col min-w-0", className)}
    >
      {label && (
        <span className="mb-1 text-xs font-medium text-muted-foreground">
          {label}
        </span>
      )}
      <span className="sr-only">
        {prefix}
        {text}
        {suffix}
      </span>
      <span
        ref={shell}
        data-slot="counter-shell"
        aria-hidden="true"
        className="relative inline-block h-[1.2em] overflow-hidden"
      >
        <span
          ref={content}
          className="absolute right-0 inline-flex w-max items-center tabular-nums"
        >
          {prefix}
          {[...text].map((glyph, index) =>
            /\d/.test(glyph) ? (
              <CounterDigit
                key={`digit-${text.length - index}`}
                digit={Number(glyph)}
                direction={direction}
                reveal={animateOnView}
              />
            ) : (
              <span key={`separator-${text.length - index}`}>{glyph}</span>
            ),
          )}
          {suffix}
        </span>
      </span>
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** Milliseconds from a CSS time such as "280ms" or ".28s" (build tools may rewrite one as the other). */
export function cssMs(value: string) {
  const text = value.trim();
  const number = parseFloat(text);
  if (!Number.isFinite(number)) return 0;
  return text.endsWith("ms") ? number : text.endsWith("s") ? number * 1000 : number;
}

/** Reads a duration token (e.g. "--duration-travel") in milliseconds from an element; the tokens resolve to 0 under reduced motion. */
export function tokenMs(element: Element, name: string) {
  return cssMs(getComputedStyle(element).getPropertyValue(name));
}

"use client";
import { useEffect, useRef, useState, type ComponentProps, type CSSProperties, type KeyboardEvent, type PointerEvent } from "react";
import { AnimatedCounter } from "./animated-counter";
import { cn } from "./lib/cn";
import "./shared/styles-5.css";
import "./ruler-slider.css";

export type RulerSliderProps = Omit<ComponentProps<"div">, "defaultValue" | "onChange"> & {
  /** Names the value, e.g. "Weight". */
  label: string;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /** A long, numbered tick every this many steps. */
  majorEvery?: number;
  /** Shown after the readout, such as "kg". */
  unit?: string;
  /** Pixels between ticks. */
  gap?: number;
};

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
const decimalsOf = (step: number) => (String(step).split(".")[1] ?? "").length;

/**
 * A tape of ticks that slides under a fixed needle. Drag it and let go: it keeps moving with the speed you gave it,
 * slows, and clicks into the nearest step while the readout rolls. Arrow keys step, Page keys jump a numbered tick,
 * Home and End go to the ends. Under reduced motion the tape lands without the glide.
 */
export function RulerSlider({ label, value, defaultValue, onValueChange, min = 0, max = 100, step = 1, majorEvery = 10, unit, gap = 10, className, style, ...props }: RulerSliderProps) {
  const [own, setOwn] = useState(() => clamp(defaultValue ?? min, min, max));
  const current = value ?? own;
  const [pos, setPos] = useState<number | null>(null); // the tape's live position while dragged or gliding, in value units
  const [detent, setDetent] = useState(0);
  const drag = useRef<{ x: number; start: number; samples: [number, number][] } | null>(null);
  const glide = useRef(0);
  const last = useRef(current);
  const decimals = decimalsOf(step);
  const snap = (raw: number) => clamp(Math.round((raw - min) / step) * step + min, min, max);

  const commit = (next: number) => {
    const snapped = Number(snap(next).toFixed(decimals));
    if (snapped === last.current) return;
    last.current = snapped;
    if (value === undefined) setOwn(snapped);
    onValueChange?.(snapped);
    setDetent((count) => count + 1);
  };

  useEffect(() => {
    last.current = current;
  }, [current]);
  useEffect(() => () => cancelAnimationFrame(glide.current), []);

  const down = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return;
    cancelAnimationFrame(glide.current);
    event.currentTarget.setPointerCapture(event.pointerId);
    const start = pos ?? current;
    drag.current = { x: event.clientX, start, samples: [[event.timeStamp, event.clientX]] };
    setPos(start);
  };
  const move = (event: PointerEvent<HTMLDivElement>) => {
    const active = drag.current;
    if (!active) return;
    // Rubber-band past the ends, so the limit is felt rather than hit.
    const raw = active.start - ((event.clientX - active.x) / gap) * step;
    const over = raw < min ? raw - min : raw > max ? raw - max : 0;
    const next = raw - over + over * 0.3;
    active.samples = [...active.samples.slice(-4), [event.timeStamp, event.clientX]];
    setPos(next);
    commit(next);
  };
  const up = () => {
    const active = drag.current;
    drag.current = null;
    if (!active || pos === null) return;
    const [[t0, x0], [t1, x1]] = [active.samples[0], active.samples[active.samples.length - 1]];
    let velocity = t1 > t0 ? (-(x1 - x0) / gap) * step / (t1 - t0) : 0; // value units per ms
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) velocity = 0;
    let at = clamp(pos, min, max);
    let then = -1;
    const frame = (now: number) => {
      const dt = then < 0 ? 16 : Math.min(32, now - then);
      then = now;
      at = clamp(at + velocity * dt, min, max);
      velocity *= Math.pow(0.994, dt);
      if (at === min || at === max) velocity = 0;
      commit(at);
      if (Math.abs(velocity) * gap / step > 0.02) {
        setPos(at);
        glide.current = requestAnimationFrame(frame);
      } else setPos(null); // the snapped value takes over and the tape eases onto it
    };
    glide.current = requestAnimationFrame(frame);
  };

  const key = (event: KeyboardEvent<HTMLDivElement>) => {
    const jumps: Record<string, number> = { ArrowRight: step, ArrowUp: step, ArrowLeft: -step, ArrowDown: -step, PageUp: step * majorEvery, PageDown: -step * majorEvery };
    if (event.key in jumps) commit(current + jumps[event.key]);
    else if (event.key === "Home") commit(min);
    else if (event.key === "End") commit(max);
    else return;
    event.preventDefault();
    cancelAnimationFrame(glide.current);
    setPos(null);
  };

  const count = Math.round((max - min) / step) + 1;
  const shown = pos ?? current;
  const text = `${current.toFixed(decimals)}${unit ? ` ${unit}` : ""}`;

  return (
    <div data-slot="ruler-slider" className={cn("grid gap-3", className)} style={{ "--rs-gap": `${gap}px`, ...style } as CSSProperties} {...props}>
      <div data-slot="rs-readout" className="flex items-baseline justify-center gap-1.5">
        <AnimatedCounter value={current} decimals={decimals} className="text-3xl font-semibold tracking-tight" />
        {unit && <span className="text-sm text-muted-foreground">{unit}</span>}
      </div>
      <div
        role="slider"
        tabIndex={0}
        aria-label={label}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={current}
        aria-valuetext={text}
        data-slot="rs-window"
        data-dragging={pos !== null ? "" : undefined}
        onPointerDown={down}
        onPointerMove={move}
        onPointerUp={up}
        onPointerCancel={up}
        onKeyDown={key}
      >
        {/* The fade sits on a still layer: a mask on the moving tape would travel with it. */}
        <div data-slot="rs-fade">
          <div data-slot="rs-tape" style={{ "--rs-at": (shown - min) / step } as CSSProperties}>
            {Array.from({ length: count }, (_, i) => {
              const major = i % majorEvery === 0;
              const half = !major && majorEvery % 2 === 0 && i % (majorEvery / 2) === 0;
              return (
                <span key={i} data-slot="rs-tick" data-major={major ? "" : undefined} data-half={half ? "" : undefined} style={{ "--rs-i": i } as CSSProperties}>
                  {major && <span data-slot="rs-number">{(min + i * step).toFixed(decimals)}</span>}
                </span>
              );
            })}
          </div>
        </div>
        <span key={detent} data-slot="rs-needle" aria-hidden="true" />
      </div>
    </div>
  );
}

/* animated-counter.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="counter-shell"] {
    transition: width var(--duration-deliberate) var(--ease-out);
  }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="counter-shell"] {
      transition: none;
    }
  }
}

/* Shared by not-found-compass.tsx, rating.tsx, ruler-slider.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-half="north"] { fill: var(--foreground); }
  [data-half="north-shade"] { fill: color-mix(in oklab, var(--foreground) 70%, var(--background)); }
  [data-half="south"] { fill: var(--border); }
}

/* ruler-slider.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Ruler slider: the tape slides under a fixed needle; it follows the finger, then eases onto the step. */
  [data-slot="ruler-slider"] [data-slot="rs-window"] { position: relative; height: 64px; overflow: hidden; border-radius: var(--radius-control); cursor: grab; touch-action: pan-y; outline: none; user-select: none; -webkit-user-select: none; }
  [data-slot="ruler-slider"] [data-slot="rs-window"][data-dragging] { cursor: grabbing; }
  [data-slot="ruler-slider"] [data-slot="rs-window"]:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }
  [data-slot="ruler-slider"] [data-slot="rs-fade"] { position: absolute; inset: 0; overflow: hidden; mask-image: linear-gradient(90deg, transparent, #000 22%, #000 78%, transparent); }
  [data-slot="ruler-slider"] [data-slot="rs-tape"] { position: absolute; inset: 0; translate: calc(var(--rs-at) * var(--rs-gap) * -1) 0; transition: translate var(--duration-deliberate) var(--ease-settle); }
  [data-slot="ruler-slider"] [data-dragging] [data-slot="rs-tape"] { transition: none; }
  [data-slot="ruler-slider"] [data-slot="rs-tick"] { position: absolute; top: 8px; left: calc(50% + var(--rs-i) * var(--rs-gap)); width: 1px; height: 10px; margin-left: -0.5px; background: var(--border-strong); }
  [data-slot="ruler-slider"] [data-slot="rs-tick"][data-half] { height: 15px; }
  [data-slot="ruler-slider"] [data-slot="rs-tick"][data-major] { width: 1.5px; height: 22px; margin-left: -0.75px; background: var(--muted-foreground); }
  [data-slot="ruler-slider"] [data-slot="rs-number"] { position: absolute; top: 28px; left: 50%; translate: -50% 0; font-size: 12px; font-variant-numeric: tabular-nums; color: var(--muted-foreground); white-space: nowrap; }
  [data-slot="ruler-slider"] [data-slot="rs-needle"] { position: absolute; top: 4px; left: 50%; width: 2px; height: 32px; margin-left: -1px; border-radius: 999px; background: var(--foreground); transform-origin: top; animation: rs-detent 240ms var(--ease-out); pointer-events: none; }
  @media (pointer: coarse) { [data-slot="ruler-slider"] [data-slot="rs-window"] { height: 72px; } }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="ruler-slider"] [data-slot="rs-tape"] { transition: none; }
    [data-slot="ruler-slider"] [data-slot="rs-needle"] { animation: none; }
  }
  @keyframes rs-detent { from { scale: 1 1.2; } }
}
